/**
 * Material3 1.4.0's [TooltipAnchorPosition.Start]/[TooltipAnchorPosition.End] caret handling is
 * broken for tooltips placed to the LEFT of their anchor (which is always the case here, since
 * the FABs are pinned to the right edge of the camera screen): `layoutCaret` applies
 * `M(p) = R(p + t)` with `t = (tooltipWidth, tooltipHeight / 2)` and `R = rotateZ(-90°)`,
 * which rotates the caret around the tooltip ORIGIN, so the caret ends up floating far to the
 * LEFT of the tooltip, pointing LEFT — instead of being attached to the right edge pointing at
 * the FABs.
 *
 * This shape feeds `layoutCaret` the PRE-IMAGE of the desired final caret under that same
 * transform, so the rendered caret becomes a triangle attached to the tooltip's right edge,
 * pointing RIGHT (toward the FABs).
 */
@OptIn(ExperimentalMaterial3Api::class)
private class RightPointingCaretShape(
    private val caretSize: DpSize = TooltipDefaults.caretSize,
) : Shape {
    override fun createOutline(
        size: Size,
        layoutDirection: LayoutDirection,
        density: Density,
    ): Outline {
        val caretWidthPx = with(density) { caretSize.width.toPx() }
        val caretHeightPx = with(density) { caretSize.height.toPx() }
        val tooltipWidth = size.width
        val tooltipHeight = size.height
        val halfHeight = tooltipHeight / 2f
        // Desired final caret (after M is applied):
        //   apex:  (tooltipWidth + caretHeightPx, tooltipHeight / 2)
        //   base1: (tooltipWidth, tooltipHeight / 2 - caretWidthPx / 2)
        //   base2: (tooltipWidth, tooltipHeight / 2 + caretWidthPx / 2)
        // Pre-image under M(x, y) = (-(y + tooltipHeight / 2), x + tooltipWidth):
        val path = Path().apply {
            moveTo(halfHeight - tooltipWidth, -tooltipWidth - caretHeightPx - halfHeight)
            lineTo(halfHeight - caretWidthPx / 2f - tooltipWidth, -tooltipWidth - halfHeight)
            lineTo(halfHeight + caretWidthPx / 2f - tooltipWidth, -tooltipWidth - halfHeight)
            close()
        }
        return Outline.Generic(path)
    }
}

/** Single instance for [RichTooltip.caretShape]: it only depends on a constant [DpSize]. */
@OptIn(ExperimentalMaterial3Api::class)
private val RightPointingCaret: Shape = RightPointingCaretShape(DpSize(14.dp, 7.dp))

@OptIn(ExperimentalPermissionsApi::class, ExperimentalMaterial3Api::class)
@Composable
fun CameraComponent(
    pictureCount: Int = 1,
    content: @Composable (() -> Unit)? = null,
    onNextPhoto: (() -> Unit)? = null,
    isDefaultBackCamera: Boolean = true,
    onPictureResult: (List<Bitmap>) -> Unit
) {
    val cameraPermission = rememberPermissionState(android.Manifest.permission.CAMERA)
    val hapticFeedback = LocalHapticFeedback.current
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background)
    ) {
        val snackbarHost = LocalSnackbarHostState.current
        if (cameraPermission.status == PermissionStatus.Granted) {
            val application = LocalActivity.current!!
            val future = remember { ProcessCameraProvider.getInstance(application) }
            val imageCapture = remember { ImageCapture.Builder().build() }
            val previewView = remember { PreviewView(application) }
            val preview = remember { Preview.Builder().build() }
            var takeImage by remember { mutableStateOf<Bitmap?>(null) }
            val takeProcessedImage by remember(takeImage) {
                derivedStateOf {
                    if (takeImage == null) null
                    else {
                        if (takeImage!!.allocationByteCount > 104857600L) {
                            snackbarHost.displaySnackbar("图片过大，无法显示预览", coroutineScope)
                            null
                        } else takeImage!!.asImageBitmap()
                    }
                }
            }
            var isBackCamera = remember { isDefaultBackCamera }
            val lifecycleOwner = LocalLifecycleOwner.current
            val photoList = remember { mutableListOf<Bitmap>() }
            var needTakePictureCount by remember { mutableIntStateOf(pictureCount) }
            DisposableEffect(lifecycleOwner) {
                future.addListener({
                    val cameraProvider = future.get()
                    cameraProvider.unbindAll()
                    preview.surfaceProvider = previewView.surfaceProvider
                    cameraProvider.bindToLifecycle(
                        lifecycleOwner,
                        if (isBackCamera) CameraSelector.DEFAULT_BACK_CAMERA else CameraSelector.DEFAULT_FRONT_CAMERA,
                        preview,
                        imageCapture
                    )
                }, ContextCompat.getMainExecutor(application))

                onDispose {
                    future.get().unbindAll()
                }
            }
            AndroidView(
                factory = { previewView },
                modifier = Modifier.fillMaxSize()
            )
            var job: Job? = remember { null }
            Box(modifier = Modifier.align(Alignment.Center)) {
                AnimatedContent(
                    takeProcessedImage,
                    modifier = Modifier.zIndex(2f),
                    transitionSpec = {
                        (fadeIn(animationSpec = tween(220, delayMillis = 90)) +
                                scaleIn(
                                    initialScale = 0.96f,
                                    animationSpec = tween(220, delayMillis = 90)
                                ) +
                                slideInHorizontally(
                                    animationSpec = tween(220, delayMillis = 90),
                                    initialOffsetX = { -it / 4 })
                                )
                            .togetherWith(
                                fadeOut(animationSpec = tween(180)) + slideOutHorizontally(
                                    animationSpec = tween(180),
                                    targetOffsetX = { it / 4 }
                                ))
                    }) {
                    if (it != null) {
                        Box(
                            modifier = Modifier
                                .fillMaxSize(0.8f)
                                .border(4.dp, Color.White, RectangleShape)
                        ) {
                            Image(
                                it,
                                null
                            )
                        }
                    }
                    LaunchedEffect(it) {
                        job = launch {
                            delay(500.milliseconds)
                            takeImage = null
                        }
                    }
                }
            }
            val gallerySingle = rememberLauncherForActivityResult(
                contract = ActivityResultContracts.PickVisualMedia(),
                onResult = { uri ->
                    if (uri == null) return@rememberLauncherForActivityResult
                    runCatching {
                        val image = application.contentResolver.openInputStream(uri).use {
                            BitmapFactory.decodeStream(it)
                        }
                        photoList.add(image)
                        job?.cancel()
                        takeImage = image
                        needTakePictureCount--
                        hapticFeedback.performHapticFeedback(HapticFeedbackType.ContextClick)
                        if (needTakePictureCount <= 0) {
                            onPictureResult(photoList)
                        } else {
                            onNextPhoto?.invoke()
                        }
                    }.onFailure {
                        it.snackbarReport(
                            snackbarHost,
                            coroutineScope,
                            "选择图片失败",
                            hapticFeedback
                        )
                        hapticFeedback.performHapticFeedback(HapticFeedbackType.Reject)
                    }
                }
            )
            val galleryMultiple = rememberLauncherForActivityResult(
                contract = ActivityResultContracts.PickMultipleVisualMedia(),
                onResult = { uris ->
                    if (uris.isEmpty()) return@rememberLauncherForActivityResult
                    runCatching {
                        uris.forEach { uri ->
                            val image = application.contentResolver.openInputStream(uri).use {
                                BitmapFactory.decodeStream(it)
                            }
                            photoList.add(image)
                            takeImage = image
                            needTakePictureCount--
                        }
                        job?.cancel()
                        hapticFeedback.performHapticFeedback(HapticFeedbackType.ContextClick)
                        if (needTakePictureCount <= 0) {
                            onPictureResult(photoList)
                        } else {
                            onNextPhoto?.invoke()
                        }
                    }.onFailure {
                        it.snackbarReport(
                            snackbarHost,
                            coroutineScope,
                            "选择图片失败",
                            hapticFeedback
                        )
                        hapticFeedback.performHapticFeedback(HapticFeedbackType.Reject)
                    }
                }
            )
