                    verticalArrangement = Arrangement.Bottom,
                    horizontalAlignment = Alignment.End,
                    modifier = Modifier
                        .align(Alignment.BottomEnd)
                        .zIndex(1f)
                        .padding(22.dp)
                ) {
                    TooltipBox(
                        onDismissRequest = {},
                        positionProvider = TooltipDefaults.rememberTooltipPositionProvider(
                            TooltipAnchorPosition.Start,
                            13.dp
                        ), modifier = Modifier.zIndex(2f), hasAction = true,
                        tooltip = {
                            RichTooltip(
                                maxWidth = 200.dp, caretShape = remember {
                                    RightPointingCaret
                                }
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.Center,
                                    modifier = Modifier.padding(2.dp, 6.dp, 0.dp, 6.dp)
                                ) {
                                    Text(
                                        tooltipText,
                                        modifier = Modifier.weight(1f)
                                    )
                                    IconButton(
                                        onClick = {
                                            tooltipState.dismiss()
                                            coroutineScope.launch(Dispatchers.IO) {
                                                context.chaoxingDataStore.updateData {
                                                    it.toBuilder().setLearntTooltips(
                                                        it.learntTooltips.toBuilder()
                                                            .setCameraSelectedFromGallery(
                                                                true
                                                            )
                                                            .apply {
                                                                if (pictureCount > 1)
                                                                    setCameraSelectedMultipleImagesFromGallery(
                                                                        true
                                                                    )
                                                            }
                                                            .build()
                                                    ).build()
                                                }
                                            }
                                        },
                                        modifier = Modifier.size(32.dp)
                                    ) {
                                        Icon(
                                            painterResource(R.drawable.ic_x),
                                            contentDescription = "关闭提示"
                                        )
                                    }
                                }
                            }
                        },
                        state = tooltipState
                    ) {
                        Column {
                            AnimatedVisibility(
                                needTakePictureCount > 1,
                                enter = fadeIn(),
                                exit = fadeOut()
                            ) {
                                FloatingActionButton(onClick = {
                                    hapticFeedback.performHapticFeedback(HapticFeedbackType.ContextClick)
                                    gallerySingle.launch(
                                        PickVisualMediaRequest(
                                            ActivityResultContracts.PickVisualMedia.ImageOnly
                                        )
                                    )

                                }) {
                                    Icon(
                                        painterResource(R.drawable.ic_images),
                                        null,
                                        modifier = Modifier.size(32.dp)
                                    )
                                }
                                Spacer(modifier = Modifier.height(12.dp))
                            }
                            FloatingActionButton(onClick = {
                                hapticFeedback.performHapticFeedback(HapticFeedbackType.ContextClick)
                                gallerySingle.launch(
                                    PickVisualMediaRequest(
                                        ActivityResultContracts.PickVisualMedia.ImageOnly
                                    )
                                )
                            }) {
                                Icon(
                                    painterResource(R.drawable.ic_image),
                                    null,
                                    modifier = Modifier.size(32.dp)
                                )
                            }
                        }
                    }

                }
            }
            Box(
                modifier = Modifier
                    .padding(12.dp)
                    .zIndex(1f)
                    .align(Alignment.TopEnd)
            ) {
                IconButton(onClick = {
                    hapticFeedback.performHapticFeedback(HapticFeedbackType.ContextClick)
                    future.get().let {
                        it.unbindAll()
                        it.bindToLifecycle(
                            lifecycleOwner,
                            if (isBackCamera) CameraSelector.DEFAULT_FRONT_CAMERA else CameraSelector.DEFAULT_BACK_CAMERA,
                            preview,
                            imageCapture
                        )
                    }
                    isBackCamera = isBackCamera.not()
                }) {
                    Icon(painterResource(R.drawable.ic_switch_camera), null, tint = Color.White)
                }
            }
            content?.let {
                Column(
                    modifier = Modifier
                        .padding(12.dp)
                        .align(Alignment.TopStart)
                ) {
                    it()
                }
            }
            Surface(
                onClick = {
                    imageCapture.takePicture(
                        ContextCompat.getMainExecutor(application),
                        object : ImageCapture.OnImageCapturedCallback() {
                            override fun onCaptureSuccess(image: ImageProxy) {
                                super.onCaptureSuccess(image)
                                image.use {
                                    val bitmap = it.toBitmap()
                                    photoList.add(bitmap)
                                    job?.cancel()
                                    takeImage = bitmap
                                    needTakePictureCount--
                                    hapticFeedback.performHapticFeedback(HapticFeedbackType.ContextClick)
                                    if (needTakePictureCount <= 0) {
                                        onPictureResult(photoList)
                                    } else {
                                        onNextPhoto?.invoke()
                                    }
                                }
                            }

                            override fun onError(exception: ImageCaptureException) {
                                exception.snackbarReport(
                                    snackbarHost,
                                    coroutineScope,
                                    "拍照失败",
                                    hapticFeedback
                                )
                                hapticFeedback.performHapticFeedback(HapticFeedbackType.Reject)
                                super.onError(exception)
                            }
                        })
                }, color = Color.White,
                shape = CircleShape,
                modifier = Modifier
                    .padding(18.dp,100.dp)
                    .size(70.dp)
                    .align(Alignment.BottomCenter)
            ) {
                if (pictureCount > 1)
                    Column(
                        modifier = Modifier.fillMaxSize(),
                        verticalArrangement = Arrangement.Center,
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Crossfade(needTakePictureCount) {
                            Text(
                                text = it.toString(),
                                color = Color.Black, fontSize = 32.sp,
                                textAlign = TextAlign.Center,
                                fontFamily = FontFamily(Font(R.font.gilroy))
                            )
                        }
                    }
            }
        } else {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .background(MaterialTheme.colorScheme.background),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.Center
            ) {
                Text("请授予应用拍照权限")
                Spacer(modifier = Modifier.height(8.dp))
                Button(
                    onClick = {
                        hapticFeedback.performHapticFeedback(HapticFeedbackType.ContextClick)
                        cameraPermission.launchPermissionRequest()
                    },
                    modifier = Modifier.align(Alignment.CenterHorizontally)
                ) {
                    Text("授予")
                }
            }
        }
    }
}

