                                                .clickable {
                                                    modifiedTagIndexList[index].value =
                                                        !modifiedTagIndexList[index].value
                                                }
                                        )
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text(
                                            tagEntity.name, modifier = Modifier
